def countElements(nums):
    # Find the smallest and largest values
    min_val = nums[0]
    max_val = nums[0]
    for num in nums:
        if num < min_val:
            min_val = num
        if num > max_val:
            max_val = num

    # Count elements strictly between min and max
    count = 0
    for num in nums:
        if min_val < num < max_val:
            count += 1
    return count
